function M:onCreate()
    M.super.onCreate(self)
    self.m_tabConfig = __TAB_BTN_NODE
    self.m_parentOpenId = self.m_params.open_id
    local response = self.m_params.response
    self.m_activityData = self.m_params.response.actives[1]
    self.m_version = response.version
    self.m_isEnter = true
    self:refreshActivityDatas(response)
    self:getData()
end

-- 每日刷新
function M:everyDayRefresh(response)
    self:refreshActivityDatas(response)
end

function M:refreshActivityDatas(data)
    self.petardAactivityDatas = {}
    self.petardAactivityDatas2 = {}
    for i,v in ipairs(__TAB_BTN_NODE) do
        local user_data = UserDataManager:getActivesDataByOpenId(v.open_id)
        if user_data then
            self.petardAactivityDatas[v.open_id] = {
                activityData = user_data,
                m_version = self.m_version,
                xlsxActivity = self:getXlsxActivityByOpenId(user_data.open_id, false),
            }
        end
        if user_data == nil then
            user_data = UserDataManager:getActivesRechargeDataByOpenId(v.open_id)
            if user_data then
                self.petardAactivityDatas[v.open_id] = {
                    activityData = user_data,
                    m_version = self.m_version,
                    xlsxActivity = self:getXlsxActivityByOpenId(user_data.open_id, true),
                }
            end
        end
     
    end


    -- -- 当前开启普通的活动配置
    -- for _, itemData in pairs(data.actives) do
    --     self.petardAactivityDatas[itemData.open_id] = {
    --         activityData = itemData,
    --         m_version = self.m_version,
    --         xlsxActivity = self:getXlsxActivityByOpenId(itemData.open_id, false),
    --     }
    -- end
    -- -- 当前开启的付费活动配置
    -- for _, itemData in pairs(data.charge_actives) do
    --     self.petardAactivityDatas[itemData.open_id] =  {
    --         activityData = itemData,
    --         m_version = self.m_version,
    --         xlsxActivity = self:getXlsxActivityByOpenId(itemData.open_id, true),
    --     }
    -- end
    -- 将主活动名字存到每个子活动里
    local mainActivityName = self.petardAactivityDatas[221].xlsxActivity.name
    for _, itemData in pairs(self.petardAactivityDatas) do
        itemData.mainActivityName = mainActivityName
    end
    -- 活动相关数据赋值
    for _, itemData in pairs(self.m_tabConfig) do
        local openId = itemData.open_id
        if self.petardAactivityDatas[openId] then
            if (openId == 222) then
                -- 签到有礼
                self.petardAactivityDatas[openId].serverData = data.sign_done
            elseif (openId == 223) then
                -- 花火集会
                self.petardAactivityDatas[openId].serverData = {
                    taskData = data.quests,
                    score = data.score,
                    scoreTaskData = data.score_done,
                }
            elseif openId == 224 then
                 -- 花火商城
                self.petardAactivityDatas[openId].serverData = {
                    consume = data.consume,
                    shop_goods = data.shop_goods,
                }
            elseif openId == 306 then
                 -- 返现礼包
                self.petardAactivityDatas[openId].serverData = {
                    gift_log = data.gift_log,
                    clothes_done = data.clothes_done,
                }
            end
        end
    end
end

function M:getActivityDataByOpenId(openId)
    if self.petardAactivityDatas then
        return self.petardAactivityDatas[openId]
    end
    return nil
end

function M:getXlsxActivityByOpenId(openId, isRechargeActivity)
    local xlsxName = isRechargeActivity and "active_recharge" or "active"
    local active = ConfigManager:getCfgByName(xlsxName)
    for _,itemData in pairs(active) do
        if (itemData.version == self.m_version) and (openId == itemData.open_id) then
            return itemData
        end
    end
    return nil
end

